import{_ as r,a}from"./chunks/660700f856f9ce7a5ab8.Co-sNTkS.js";import{_ as o,C as n,o as i,c as l,j as e,a as s,E as m,a6 as h}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"如何不再对未来感到迷茫、不知所措与充满不确定感","description":"","frontmatter":{"title":"如何不再对未来感到迷茫、不知所措与充满不确定感","originalTitle":"How To Stop Feeling Lost, Overwhelmed, & Uncertain About The Future","date":"2022-10-02","originalUrl":"https://thedankoe.com/letters/the-cure-to-caring-what-people-think/","minutes":10,"sourceHash":"bd119331905dc44d03519b47d93bf87d641944a2d1d668615d191405284dd98e","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-cure-to-caring-what-people-think/"}]]},"headers":[],"relativePath":"letters/the-cure-to-caring-what-people-think.md","filePath":"letters/the-cure-to-caring-what-people-think.md"}'),c={name:"letters/the-cure-to-caring-what-people-think.md"};function d(g,p,u,_,f,b){const t=n("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=e("h1",{id:"如何不再对未来感到迷茫、不知所措与充满不确定感",tabindex:"-1"},[s("如何不再对未来感到迷茫、不知所措与充满不确定感 "),e("a",{class:"header-anchor",href:"#如何不再对未来感到迷茫、不知所措与充满不确定感","aria-label":'Permalink to "如何不再对未来感到迷茫、不知所措与充满不确定感"'},"​")],-1)),m(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/7lFBZQzu8nk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>问题不是针对个人的。</p><p>问题是系统性的。</p><p>每个人都有相同的问题，而且他们会继续面临这些相同的问题。</p><p>你永远无法逃避它们。</p><p>你只能在看待问题的方式上变得更好，从而做出更好的决策（不受情绪影响）。</p><p><img src="'+r+'" alt=""></p><p>在这封信中，我想为问题提供一种新的视角，帮助你思考得更深、做得更好、成为更好的人。</p><p>焦虑、不知所措和压力都是心理熵（psychic entropy）的结果。</p><p>什么是心理熵？</p><p>心理（Psychic） = 关于头脑的。</p><p>熵（Entropy） = 系统趋向无序的状态。</p><p>系统需要持续的能量才能蓬勃发展。</p><p>如果你的头脑是一个房间，而你不投入能量去打扫它（维持秩序），那么这个房间就会变脏。</p><p>一天不打扫还没什么。但一周后呢？一个月？一年呢？朋友们，那就是我们所说的猪圈了。</p><p>难怪焦虑在我们的社会中如此猖獗。没有人能在一年不打扫房间后，还愿意投入那么大的精力去清理。隔天打扫一次可比隔年打扫容易多了。焦虑的循环仍在继续，因为我们<em>知道</em>需要打扫房间，但我们没有去行动。在思想和行动之间存在着一条鸿沟。</p><p>问题就恰好出现在这里。</p><p>当作为我们头脑的这个系统出现了能量堵塞时。</p><p>心理健康关乎<em>理清头绪、理解和清晰度</em>。</p><p>如果你任由强迫性和消极的念头劫持一个情境，你就无法看清它的本来面目。</p><p>你会困在自己的脑海里，去想那些<em>可能</em>发生的坏事。你把那种负面体验拽到了现在，而它影响了你的思想和行动。</p><p>注意力为它触及的一切注入生命。</p><p>当你把注意力集中在你头脑创造的虚假现实中时，你的行为方式就会让它变成<em>现实</em>。</p><p><em>你觉得这在任何情况下会带来有益的结果吗？</em></p><p>它能帮助你实现社交、财务或个人目标吗？还是说，它会扭曲这些目标，让你退缩回舒适区？</p><h3 id="这一课" tabindex="-1">这一课 <a class="header-anchor" href="#这一课" aria-label="Permalink to &quot;这一课&quot;">​</a></h3><p><img src="'+a+'" alt=""></p><p>要明白，你的问题都很正常。</p><p>它们是头脑的捏造，通过注意力才变得真实。</p><p>问题并不特殊，当你换个角度审视时，它们就会显得很蠢。</p><p>为什么当一个第三世界国家的孩子都已经接受了明天可能没有水喝时，你却还在担心自己的社交媒体帖子零互动？那个孩子怎么会在心理状态上比你更好？</p><p>通过获取新的视角，你创造了空间，可以从那个吞噬了你注意力的全局问题中抽离出来。这个问题就会从整个世界那么大缩小到只有面包屑一般大小。</p><p>你可以<em>看清</em>问题的本质，通过觉察，开始纠正在生活中消耗能量的方式，以维持心智的秩序。</p><h2 id="在你自己的现实中运作" tabindex="-1">在你自己的现实中运作 <a class="header-anchor" href="#在你自己的现实中运作" aria-label="Permalink to &quot;在你自己的现实中运作&quot;">​</a></h2><p>你该如何在头脑中维持秩序，以避免可怕的焦虑、不知所措和压力？</p><p>通过创造你自己的现实。</p><p>Dan，这他妈的到底是什么意思？</p><p>系统需要能量。</p><p>你的头脑就是一个系统。</p><p>精神能量是通过注意力传递的。</p><p>“注意力在哪里，能量就流向哪里。”</p><p>当你关注积极的事物时，生活就是积极的。</p><p>当你关注消极的事物时，生活就是消极的。</p><p>虽说这可以瞬间改变，但你必须明白，你是过去的产物。</p><p>你的头脑最初是一块<em>接近</em>空白的画板。随着时间的推移，它被条件反射式地塑造，以一种有利于社会和文化发展的方式运作。没有别的路可走。这就是你学习的方式。</p><p>我们把父母的信念、朋友的行为举止以及我们文化中的问题全盘接受，就好像它们是我们自己的一样。</p><p>再说一次，这本身并不是“坏事”。但如果你想从生活中得到更多（不然你为什么要读这篇通讯？），我就能想象你连连摇头的样子了。</p><p>俗话常说“你的思想创造了你的现实”，确实如此，但又是什么让你的思想（你的现实）变好或变坏的呢？</p><p>如果我们的信念是被编程到我们脑海中的，而我们的信念又倾向于让思想自动化，那我们该怎么办？难道我们就只能接受被教导的一切以及随之而来的情感包袱吗？</p><p>生活在一个你被条件化塑造成的现实中，就像做一个提线木偶。一个 NPC。一个受除了你自己之外任何人控制的情绪开关。</p><p>为了扭转这种效应，我们必须掌控那些我们拥有完全控制权的机能：</p><ul><li><strong>你的视角（perspective）</strong>——你观察一个情境的角度或立场。</li><li><strong>你的感知（perception）</strong>——你如何诠释这个情境。它是有问题的还是有益的？</li></ul><p>结合起来看，视角 + 感知 = 焦点。</p><p>焦点 = 有意识的注意力。</p><p>焦点是可以被控制的。可以放大、缩小、变窄、变宽、打开、关闭。</p><p>焦点是你互动、诠释并决定把宝贵的能量投入到哪里的方式。</p><p>焦点就是你（和你的头脑）与你所处的任何外部环境互动的方式。</p><p>我说的是不是深度工作（deep work）意义上的那种专注。</p><p>我说的是焦点，它是你此时此刻、在你的全部过去以及整个未来正在做的事情。</p><p>千万不要等闲视之。</p><p>注意力是你唯一能有意识控制的东西。</p><p>当一个无法控制的念头跳进你的脑海时，你有两个选择：</p><ol><li><p>让你的注意力保持自动和无意识的状态——这几乎注定你会对自己正在接收的念头、想法或信息做出消极的诠释。</p></li><li><p>观察你的注意力、你的反应，并通过做出有利于你目标的诠释来修正方向，我们将在下文中讨论这一点。</p></li></ol><p>当我们在这一生中让这个过程（即焦点）变得有意识时，我们的生活质量就会飙升。为什么？因为我们慢慢开始意识到，我们可能想要的一切都是通过我们如何投资“焦点”这种货币来实现的。投资是会产生复利的。</p><h2 id="治愈焦虑的良药-始终带有意图地行动" tabindex="-1">治愈焦虑的良药：始终带有意图地行动 <a class="header-anchor" href="#治愈焦虑的良药-始终带有意图地行动" aria-label="Permalink to &quot;治愈焦虑的良药：始终带有意图地行动&quot;">​</a></h2><p>你的现实就是一个框架。</p><p>视角是相机，感知是镜头。</p><p>当你的注意力完全聚焦于你的现实之内时，所有的烦恼都会烟消云散。</p><p>我们将在另一封信中讨论如何建立更好的关系，但简而言之：你通过找到一个共同的视角来分享，从而建立更好的关系——一个你们双方都能投入最大能量并解决所产生问题的共同现实。</p><p>想想看，一个健美运动员会介意带鸡肉和米饭去参加家庭聚餐吗？会的，但前提是他将自己投射到了他的现实之外。也就是说，只有当他失去对注意力的控制时才会。</p><p>如果他记得什么对他来说最重要、记得他的目标，并能正确感知情况以避免短期享乐，那他就不会在乎。也就是说，他保持着专注。</p><p>其他事情真的重要吗？</p><p>重要，但只有在你给予关注的时候才重要。毫不夸张地说，只有当你给予注意力时，它才会存在——存在于你的意识觉察之中。</p><p>如果你无法给予它注意力，它还会存在吗？当然不会，至少对你来说是不存在的。</p><p>如果有不受控制的念头、观点或信念跳入你的觉知视野（由你焦点的宽度决定），请把注意力拉回到你的现实中。</p><p>简而言之，要摆脱焦虑、在意别人的看法以及心理熵——你必须掌控你的焦点。</p><p>你必须把机械般的生活换成<em>有意图的（intentional）</em>生活。</p><p>源自拉丁语 <em>intentio:</em></p><p><em>‘伸展、目的’</em></p><p>你正在朝着什么<em><strong>伸展</strong></em>？</p><p>你能告诉我吗？你是每天都在这么做，还是只在“觉得想做”的时候才做？</p><p><em>如果你没有去追求一种有目标的生活——向着比你自己更宏大的事物伸展——那么你只是在生存</em>_。那是一种无意识、机械且自动的无意义状态。只是社会机器上的一个齿轮而已。_</p><p>最后，我们该如何摆脱这种永远感到迷茫、焦虑且对生活失去控制感的状态？</p><p>通过建造、构筑并积极创造你想要的未来。</p><p>请理解，这些用词都是有意图的。</p><p>你不可能一天“建好”一栋房子。</p><p>如果没有相应的资源，你不可能“构筑”出一种生活。</p><p>在地基打好之前，你可能都看不到建筑露出地面。但一旦房子的骨架显现出来，动力就会自然而然地产生。</p><p>以下是你需要做的：</p><p><strong>1) 设定一个有意义的目标</strong></p><p>这一步绊倒了大多数人。</p><p>一个系统需要一个<em>结果</em>。</p><p>你需要有一些能够<em>倾注能量</em>的东西。</p><p>如果你没有在生活的任何领域取得进展（没错，即使是通过“什么都不做”或休息一下而在精神领域取得进展也算），那么能量就没有在正常流动。</p><p>动力源自于行动。</p><p>建造粗劣的房子会被推倒，然后重建。</p><p>“但是 Dan，我该如何创造一个有意义的目标呢？”</p><p>首先，不要抱有<strong>它会很容易、立竿见影或者毫不费力的虚假期望。</strong></p><p>如果你不知道该做什么，那么字面意义上唯一的选择就是<strong>尝试新事物</strong>。没有人能告诉你什么对你有意义。</p><p>去试试那种商业模式。</p><p>去了解你那个奇怪的兴趣。</p><p>听取某个（你尊敬的人）的建议，然后去实验。</p><p>去做任何事情，只要不是在手机上无脑滑屏并抱怨你的生活现状就行。</p><p>给点时间，你会找到一个你想“全盘投入（all in）”的东西。</p><p>你怎么知道什么时候该全盘投入呢？</p><p>你会情不自禁的。</p><p>如果你不是活在一个永远分心的状态里，那个目标带来的兴奋感就会推动你采取行动。</p><p><strong>2) 建立一个系统</strong></p><p>如果你没有计划，就别指望能得到不靠运气驱动的结果。</p><p>世界上收入最高的人是创新者、战略家和有远见的人。而不是体力劳动者。</p><p>成为一名战略家。</p><p>今晚拿出一本笔记本，坐下来花个 30 分钟。</p><p>画出你的未来。写下你为了达成目标确切要去做的事。</p><p>现在，你要明白大多数目标都是通过系统来实现的。</p><p>一个流程。</p><p>流程是重复的、基于基本原理的，并且会随着经验的积累而改进。</p><p>你在每天、每周和每月要撬动哪些杠杆？</p><p>把它们写下来。</p><p>因为只有这样，也唯有这样，你才能去努力改进那个流程。</p><p>你无法改进不存在的东西。</p><p>所以，去创造出你可以改进的东西。</p><p><strong>3) 汇聚</strong> <strong>所有</strong> <strong>能量到该目标上</strong></p><p>能量有两种形式，外在的和内在的。</p><p>通过朝着让你兴奋的目标努力，你会获得优质多巴胺的驱动，因为多巴胺来自于想要实现你愿景的渴望。</p><p>这就是内在能量。如果你失去了对目标的最初兴奋感，你可能需要提醒自己当初为什么要开始。</p><p>另一种形式的能量，即外在能量，来自于将你的所有<em>思想、情感和行动</em>汇聚到那个目标上。</p><p>重新框架你遇到的<em>一切事物</em>，从你目标的视角去看待它们。</p><p>重新框架 = 转化。</p><p>同一枚硬币总有两面。积极的一面和消极的一面。</p><p>大多数人图方便地忽略了积极的一面，这样他们就有借口停止追求目标了。</p><p>你必须掌控自己的注意力。</p><p>最好的方法是带着意图去问“为什么”。</p><p>为什么你要吃那种平淡无味却能提供能量的食物？为了实现你的体型目标。</p><p>为什么你要写那些一开始根本毫无起色的帖子？为了实现你的财务自由目标。</p><p>为什么在公共场合即使显得“格格不入”，你也要去和一个陌生人交谈？为了实现你的社交目标。</p><p>心理。秩序。</p><p>如果你无法回答自己正在做的事是“为了什么”，那你为什么还要去做？</p><p>这说不通。心理健康就在于让一切说得通。</p><p>我再问一次：</p><p>你在朝什么方向<em>拓展</em>？</p><p>单凭这一点，就能带来必要的清晰度，避免你因为过度关注生活中的消极面而陷入下坠的恶性循环。</p><h3 id="本周动态" tabindex="-1">本周动态 <a class="header-anchor" href="#本周动态" aria-label="Permalink to &quot;本周动态&quot;">​</a></h3><p>Digital Economics 将在<em>下周</em>开放报名。如果你有兴趣掌握一人企业的四大支柱（品牌、内容、营销和产品），请查看下方内容。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">了解 Digital Economics。</a></p><p>一期名为《如果你具备高价值，那就创办一家一人企业》的 YouTube 视频刚刚上线。</p><p><a href="https://youtu.be/sgXAQDTa3dA" target="_blank" rel="noreferrer">点击此处观看。</a></p><p>在 Modern Mastery 中，Joey 发布了一篇关于如何创建和推广引流品（lead magnet）的文章，这对于任何试图建立一人企业的人来说都至关重要。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者仅需 5 美元即可加入。</a></p><p>周一上线了一期播客，标题为《98% 的人因为这个鲜为人知的原因感到焦虑》。你可以把它看作是这篇通讯文章的扩充版。</p><p><a href="https://open.spotify.com/episode/1XA5jvE1pP5Rk1aHtlHaOB?si=8dbdcb70440747a3" target="_blank" rel="noreferrer">收听播客。</a></p><hr><p><a href="/en/letters/the-cure-to-caring-what-people-think">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',152))])}const w=o(c,[["render",d]]);export{P as __pageData,w as default};
